import { Draggable } from "react-beautiful-dnd";
import { Col, Input, Label, Row, FormFeedback } from "reactstrap";
import { Button } from "reactstrap";
import { MdDragIndicator } from "react-icons/md";
import { FaRegTrashAlt } from "react-icons/fa";
import Select from "react-select";
import { selectThemeColors } from "@utils";
import { DIRECTION_DATA } from "../../../../utility/Utils";

const Flow = ({
  item,
  index,
  session,
  sessionIndex,
  updateSubscriberController,
  rule,
  ruleIndex,
  flow,
  flowIndex,
  validations,
  showValidations,
}) => {
  return (
    <Draggable
      key={`flow-${flowIndex}`}
      draggableId={`flow-${flowIndex}`}
      index={flowIndex}
    >
      {(provided) => (
        <div
          className={"mb-1 rounded"}
          key={flowIndex}
          ref={provided.innerRef}
          {...provided.draggableProps}
        >
          <Row
            style={{
              padding: "16px",
              border: "1px solid rgb(215,215,215)",
              background: "rgba(215,215,215,.4)",
            }}
            className={"rounded"}
          >
            <div
              className={
                "d-flex align-items-center justify-content-between mb-2"
              }
            >
              {/* session badge */}
              <div
                className="text-white d-flex justify-content-center align-items-center rounded"
                style={{
                  background: "#07274E",
                  padding: "0 8px",
                  height: 30,
                  cursor: "grab",
                }}
                {...provided.dragHandleProps}
              >
                <button
                  style={{
                    transform: "rotate(90deg)",
                  }}
                  className="border-0 bg-transparent mr-1"
                >
                  <MdDragIndicator
                    className="text-white"
                    fontSize={24}
                    style={{
                      cursor: "grab",
                    }}
                  />
                </button>
                Flow {flowIndex + 1}
              </div>
              {/* slice delete button */}
              {flowIndex > 0 ? (
                <Button
                  color="danger"
                  size="sm"
                  type="button"
                  onClick={() => {
                    let prevArray = [...rule.flow];
                    prevArray = prevArray.filter((o, ind) => ind != flowIndex);
                    updateSubscriberController.setFieldValue(
                      `slice[${index}].session[${sessionIndex}].pcc_rule[${ruleIndex}].flow`,
                      prevArray
                    );
                  }}
                >
                  <FaRegTrashAlt />
                </Button>
              ) : null}
            </div>
            {/* direction */}
            <Col xs="12" sm="6" className={"mb-1"}>
              <Label for="direction" style={{ position: "relative" }}>
                Flow Direction{" "}
                <div
                  style={{
                    color: "red",
                    fontSize: 18,
                    position: "absolute",
                    right: -16,
                    top: -2,
                  }}
                >
                  *
                </div>
              </Label>
              <Select
                isClearable={false}
                theme={selectThemeColors}
                closeMenuOnSelect={true}
                placeholder="select option"
                maxMenuHeight={120}
                options={DIRECTION_DATA}
                className={`react-select`}
                classNamePrefix="select"
                id="direction"
                name="direction"
                value={flow.direction}
                onChange={(value) => {
                  updateSubscriberController.setFieldValue(
                    `slice[${index}].session[${sessionIndex}].pcc_rule[${ruleIndex}].flow[${flowIndex}].direction`,
                    value
                  );
                }}
              />
            </Col>
            {/* description */}
            <Col xs="12" sm="6" className={"mb-1"}>
              <Label for="direction" style={{ position: "relative" }}>
                Description{" "}
                <div
                  style={{
                    color: "red",
                    fontSize: 18,
                    position: "absolute",
                    right: -16,
                    top: -2,
                  }}
                >
                  *
                </div>
              </Label>
              <Input
                value={flow.description}
                onChange={(e) => {
                  updateSubscriberController.setFieldValue(
                    `slice[${index}].session[${sessionIndex}].pcc_rule[${ruleIndex}].flow[${flowIndex}].description`,
                    e.target.value
                  );
                }}
                name="description"
                id="description"
                className={
                  showValidations &&
                  validations[
                    `session_{${sessionIndex}}_rule_${ruleIndex}_flow_description_${flowIndex}`
                  ]?.length > 0
                    ? "form_error"
                    : null
                }
              />
              {showValidations &&
              validations[
                `session_{${sessionIndex}}_rule_${ruleIndex}_flow_description_${flowIndex}`
              ]?.length > 0 ? (
                <FormFeedback style={{ display: "block" }}>
                  {
                    validations[
                      `session_{${sessionIndex}}_rule_${ruleIndex}_flow_description_${flowIndex}`
                    ]
                  }
                </FormFeedback>
              ) : null}
            </Col>
          </Row>
        </div>
      )}
    </Draggable>
  );
};
export default Flow;
