import { Draggable, Droppable, DragDropContext } from "react-beautiful-dnd";
import { FormFeedback, Row } from "reactstrap";
import { Button, Col, Label, Input } from "reactstrap";
import { MdDragIndicator, MdDone } from "react-icons/md";
import { FaRegTrashAlt } from "react-icons/fa";
import SessionComponent from "./session";
import toast from "react-hot-toast";

const SliceComponent = ({
  item,
  index,
  updateSubscriberController,
  handleChangeSst,
  handleDragSession,
  handleDragPccRule,
  handleDragFlow,
  validations,
  showValidations,
}) => {
  return (
    <Draggable
      key={`slice-${index}`}
      draggableId={`slice-${index}`}
      index={index}
    >
      {(provided) => (
        <div
          className={"mb-1 rounded"}
          key={index}
          ref={provided.innerRef}
          {...provided.draggableProps}
        >
          <Row
            style={{
              border: "1px solid rgb(200,200,200)",
              padding: "16px",
              background: "rgba(220,220,220,.15)",
              width: "100%",
              marginLeft: 0,
            }}
            className={"rounded"}
          >
            <div
              className={
                "d-flex align-items-center justify-content-between mb-2"
              }
            >
              {/* slice badge */}
              <div
                className="text-white d-flex justify-content-center align-items-center rounded"
                style={{
                  background: "#07274E",
                  padding: "0 8px",
                  height: 30,
                  cursor: "grab",
                }}
                {...provided.dragHandleProps}
              >
                <button
                  style={{
                    transform: "rotate(90deg)",
                  }}
                  className="border-0 bg-transparent mr-1"
                >
                  <MdDragIndicator
                    className="text-white"
                    fontSize={24}
                    style={{ cursor: "grab" }}
                  />
                </button>
                Slice {index + 1}
              </div>
              {/* slice delete button */}
              {index > 0 ? (
                <Button
                  color="danger"
                  size="sm"
                  type="button"
                  onClick={() => {
                    let array = [...updateSubscriberController.values.slice];
                    array = array.filter((o, ind) => ind != index);
                    updateSubscriberController.setFieldValue("slice", array);
                  }}
                >
                  <FaRegTrashAlt />
                </Button>
              ) : null}
            </div>
            <Col xs="12" sm="4" className={"mb-1"}>
              <Label className={"position-relative"}>
                SST{" "}
                <div
                  className="text-danger position-absolute"
                  style={{
                    fontSize: 18,
                    right: -16,
                    top: -2,
                  }}
                >
                  *
                </div>
              </Label>
              <div className="d-flex align-items-center">
                <div
                  style={{
                    cursor: "pointer",
                    marginRight: 16,
                  }}
                  className="d-flex align-items-center"
                  onClick={() => {
                    handleChangeSst(1, index);
                  }}
                >
                  <div
                    style={{
                      width: 24,
                      height: 24,
                      borderRadius: "50%",
                      border: "1px solid rgb(200,200,200)",
                      marginRight: 8,
                    }}
                    className={item.sst == 1 ? "bg-primary" : "bg-transparent"}
                  ></div>
                  <div style={{ fontSize: 20 }}>1</div>
                </div>
                <div
                  style={{
                    cursor: "pointer",
                    marginRight: 16,
                  }}
                  className="d-flex align-items-center"
                  onClick={() => {
                    handleChangeSst(2, index);
                  }}
                >
                  <div
                    style={{
                      width: 24,
                      height: 24,
                      borderRadius: "50%",
                      border: "1px solid rgb(200,200,200)",
                      marginRight: 8,
                    }}
                    className={item.sst == 2 ? "bg-primary" : "bg-transparent"}
                  ></div>
                  <div style={{ fontSize: 20 }}>2</div>
                </div>
                <div
                  style={{
                    cursor: "pointer",
                    marginRight: 16,
                  }}
                  className="d-flex align-items-center"
                  onClick={() => {
                    handleChangeSst(3, index);
                  }}
                >
                  <div
                    style={{
                      width: 24,
                      height: 24,
                      borderRadius: "50%",
                      border: "1px solid rgb(200,200,200)",
                      marginRight: 8,
                    }}
                    className={item.sst == 3 ? "bg-primary" : "bg-transparent"}
                  ></div>
                  <div style={{ fontSize: 20 }}>3</div>
                </div>
                <div
                  style={{
                    cursor: "pointer",
                    marginRight: 16,
                  }}
                  className="d-flex align-items-center"
                  onClick={() => {
                    handleChangeSst(4, index);
                  }}
                >
                  <div
                    style={{
                      width: 24,
                      height: 24,
                      borderRadius: "50%",
                      border: "1px solid rgb(200,200,200)",
                      marginRight: 8,
                    }}
                    className={item.sst == 4 ? "bg-primary" : "bg-transparent"}
                  ></div>
                  <div style={{ fontSize: 20 }}>4</div>
                </div>
              </div>
            </Col>
            <Col xs="12" sm="4" className={"mb-1"}>
              <Label>SD</Label>
              <Input
                value={item.sd}
                onChange={(e) => {
                  const currentSlice = updateSubscriberController.values.slice;
                  const updatedSlice = currentSlice.map((item, ind) =>
                    ind === index ? { ...item, sd: e.target.value } : item
                  );
                  updateSubscriberController.setFieldValue(
                    "slice",
                    updatedSlice
                  );
                }}
                name="sd"
                id="sd"
                className={
                  showValidations && validations[`sd_${index}`]?.length > 0
                    ? "form_error"
                    : null
                }
              />
              {showValidations && validations[`sd_${index}`]?.length > 0 ? (
                <FormFeedback style={{ display: "block" }}>
                  {validations[`sd_${index}`]}
                </FormFeedback>
              ) : null}
            </Col>
            <Col xs="12" sm="4" className={"mb-1"}>
              <div
                style={{
                  cursor: "pointer",
                  marginRight: 16,
                  marginTop: 20,
                }}
                className="d-flex align-items-center"
                onClick={() => {
                  const currentSlice = updateSubscriberController.values.slice;
                  var updatedSlice;
                  if (item.default_indicator) {
                    updatedSlice = currentSlice.map((itemInside, ind) =>
                      ind === index
                        ? {
                            ...itemInside,
                            default_indicator: false,
                          }
                        : itemInside
                    );
                  } else {
                    updatedSlice = currentSlice.map((itemInside, ind) =>
                      ind === index
                        ? {
                            ...itemInside,
                            default_indicator: true,
                          }
                        : itemInside
                    );
                  }

                  updateSubscriberController.setFieldValue(
                    "slice",
                    updatedSlice
                  );
                }}
              >
                <div
                  style={{
                    width: 24,
                    height: 24,
                    borderRadius: 5,
                    border: "1px solid rgb(200,200,200)",
                    marginRight: 8,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                  }}
                  className={
                    item.default_indicator == 1
                      ? "bg-primary"
                      : "bg-transparent"
                  }
                >
                  <MdDone
                    className="text-white"
                    fontSize={18}
                    fontWeight={900}
                  />
                </div>
                <div style={{ fontSize: 16 }}>Default S-NSSAI</div>
              </div>
            </Col>
            {/* sessions */}
            <div
              className={"pb-1 mb-1 mt-2 d-flex justify-content-between"}
              style={{
                borderBottom: "1px solid rgb(180,180,180)",
              }}
            >
              <div style={{ fontWeight: 900, fontSize: 16 }}>
                Session Configurations
              </div>
              <Button
                size="sm"
                type="button"
                color="success"
                onClick={() => {
                  const currentSlice = updateSubscriberController.values.slice;
                  let sessionsArray = [...item.session];
                  sessionsArray.push({
                    dnn_apn: "internet",
                    type: { label: "IPv4v6", value: 3 },
                    qi_qci: { label: "9", value: 9 },
                    arp_priority_level: { label: "8", value: 8 },
                    capability: { label: "Disabled", value: 1 },
                    vulnerability: { label: "Disabled", value: 1 },
                    session_ambr_downlink: "1",
                    session_ambr_downlink_unit: { label: "Gbps", value: 3 },
                    session_ambr_uplink: "1",
                    session_ambr_uplink_unit: { label: "Gbps", value: 3 },
                    ue_ipv4_address: "",
                    ue_ipv6_address: "",
                    smf_ipv4_address: "",
                    smf_ipv6_address: "",
                    pcc_rule: [],
                  });
                  const updatedSlice = currentSlice.map((item, ind) =>
                    ind === index
                      ? {
                          ...item,
                          session: sessionsArray,
                        }
                      : item
                  );
                  updateSubscriberController.setFieldValue(
                    "slice",
                    updatedSlice
                  );
                }}
              >
                Add session
              </Button>
            </div>
            <DragDropContext
              onDragEnd={(result) => {
                handleDragSession(result, index);
              }}
            >
              <Droppable droppableId="sliceList">
                {(provided) => (
                  <div
                    {...provided.droppableProps}
                    ref={provided.innerRef}
                    style={{ padding: "16px 64px" }}
                  >
                    {item.session.map((session, sessionIndex) => (
                      <SessionComponent
                        item={item}
                        index={index}
                        session={session}
                        sessionIndex={sessionIndex}
                        updateSubscriberController={updateSubscriberController}
                        handleDragPccRule={handleDragPccRule}
                        handleDragFlow={handleDragFlow}
                        validations={validations}
                        showValidations={showValidations}
                      />
                    ))}
                  </div>
                )}
              </Droppable>
            </DragDropContext>
          </Row>
        </div>
      )}
    </Draggable>
  );
};
export default SliceComponent;
